import{_ as o,o as a,c as t,a5 as r}from"./chunks/framework.C588jwcu.js";const u=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"en/latest/tutorial/core/logger.md","filePath":"en/latest/tutorial/core/logger.md","lastUpdated":1785683504000}'),l={name:"en/latest/tutorial/core/logger.md"};function n(g,e,c,i,s,d){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="logger-knd-logger" tabindex="-1">Logger KND_Logger <a class="header-anchor" href="#logger-knd-logger" aria-label="Permalink to &quot;Logger KND_Logger&quot;">​</a></h1><h2 id="preface" tabindex="-1">Preface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Preface&quot;">​</a></h2><p>KND_Logger is a logging module based on the Godot Logger implementation. It supports log levels, log formats, log output, log files, and other features, and is used to record Konado runtime log information.</p><h2 id="log-path" tabindex="-1">Log Path <a class="header-anchor" href="#log-path" aria-label="Permalink to &quot;Log Path&quot;">​</a></h2><p>The logical log path is <code>user://konado_log.log</code>. Godot resolves its physical directory for the current operating system and project name; use <code>OS.get_user_data_dir()</code> to inspect it. <code>LOG_FILE_PATH</code> is a built-in constant, so changing the location requires maintaining that change in a customized plugin build.</p><h2 id="on-screen-overlay-log" tabindex="-1">On-Screen Overlay Log <a class="header-anchor" href="#on-screen-overlay-log" aria-label="Permalink to &quot;On-Screen Overlay Log&quot;">​</a></h2><p>When an error occurs, the dialogue scene overlays a log window on the screen to show error information and interrupt game execution. If you want to disable this feature, set the <code>enable_overlay_log</code> property of <code>KND_DialogueManager</code> to <code>false</code>.</p><h2 id="log-callback" tabindex="-1">Log Callback <a class="header-anchor" href="#log-callback" aria-label="Permalink to &quot;Log Callback&quot;">​</a></h2><p>A <code>KND_Logger</code> instance emits <code>error_caught(msg)</code> and <code>message_caught(message, error)</code>. When <code>KND_DialogueManager</code> enters the scene tree, it creates and registers an internal logger with Godot and uses <code>error_caught</code> to drive its overlay; the logger is not a global autoload. A custom integration that creates another <code>KND_Logger</code> must register it with <code>OS.add_logger()</code> and call <code>OS.remove_logger()</code> before freeing it to avoid duplicate logging or stale instances.</p>',9)])])}const _=o(l,[["render",n]]);export{u as __pageData,_ as default};
